const MAIN_SITE="https://findspreadsheet.com/";
const categoryLinks=["/shoes/","/hoodies-sweaters/","/t-shirts/","/jackets/","/pants-shorts/","/headwear/","/ShortSets/","/other-stuff/","/jersey/","/accessories/"];
const productLinks=["/t-shirts/cp-company-t-shirt-2993.html","/accessories/supreme-wallet-2995.html","/electronics/beats-studio-buds-wireless-headset-20-styles-664.html","/jersey/qatar-short-sleeve-suits-2249.html"];

function MainSearch({t,compact=false}:{t:Copy;compact?:boolean}){
  const[query,setQuery]=useState("");
  return <div className={compact?"search-wrap search-wrap--compact":"search-wrap"}><form className={compact?"search search--compact":"search"} action="https://findspreadsheet.com/search.html" method="get" target="_blank"><Search aria-hidden size={20}/><label className="sr-only" htmlFor={compact?"cta-search":"hero-search"}>{t.search}</label><input id={compact?"cta-search":"hero-search"} name="keywords" value={query} onChange={e=>setQuery(e.target.value)} placeholder={t.placeholder} required/><input type="hidden" name="channelid" value="2"/><button type="submit">{t.search}<ArrowRight size={17}/></button></form>{!compact&&<a className="under-database" href={MAIN_SITE} target="_blank" rel="noreferrer">{t.database}<ExternalLink size={15}/></a>}</div>
}

function LanguagePicker({locale,onChange}:{locale:Locale;onChange:(locale:Locale)=>void}){
  return <label className="language-picker"><Globe2 size={15}/><span className="sr-only">Language</span><select value={locale} onChange={event=>onChange(event.target.value as Locale)} aria-label="Language">{locales.map(code=><option key={code} value={code}>{code.toUpperCase()} · {languageNames[code]}</option>)}</select><ChevronDown size={13}/></label>
}

export function LoloSite({locale:initialLocale="en",view="home"}:{locale?:Locale;view?:SectionView|"home"}){
  const locale=initialLocale;
  const t=copy[locale]; const home=`/${locale}`; const show=(section:SectionView)=>view==="home"||view===section;
  useEffect(() => {
    document.documentElement.lang = locale;
  }, [locale]);
  function changeLocale(next:Locale){
    window.localStorage.setItem("lolobuy-language",next);
    const destination=next==="en"?`/en${view==="home"?"":`/${view}`}`:`/${next}${view==="home"?"":`/${view}`}`;
    window.location.assign(destination);
  }
  return <main lang={locale}>
    <header className="site-header"><a className="brand brand-image" href={home} aria-label="LoloBuy home"><img src="/lolobuy-logo.png" alt="LoloBuy"/></a><nav aria-label="Primary navigation">{[[t.nav[0],""],[t.nav[1],"categories"],[t.nav[2],"product-details"],[t.nav[3],"how-it-works"],[t.nav[4],"shipping"],[t.nav[5],"faq"],[t.nav[6],"seo-articles"]].map(([label,path])=><a key={path||"home"} href={path?`${home}/${path}`:home} aria-current={(view==="home"&&!path)||view===path?"page":undefined}>{label}</a>)}</nav><LanguagePicker locale={locale} onChange={changeLocale}/></header>
    {view==="home"&&<section className="hero" id="top"><div className="hero-copy"><p className="eyebrow"><Sparkles size={15}/>{t.eyebrow}</p><h1>{t.titleA} <em>{t.titleB}</em></h1><p className="hero-lede">{t.lede}</p><MainSearch t={t}/><div className="trust-line">{t.trust.map(x=><span key={x}><Check size={15}/>{x}</span>)}</div></div><div className="hero-visual"><img src="/hero-warehouse.png" alt="Organized unbranded clothing and recyclable parcels on a quality-control table"/><div className="visual-note visual-note--top"><span>{t.visualTop}</span><strong>{t.visualTitle}</strong></div><div className="visual-note visual-note--bottom"><ShieldCheck size={24}/><span><strong>{t.visualStrong}</strong><small>{t.visualSmall}</small></span></div></div></section>}
    {show("categories")&&<section className="category-section" id="categories"><div className="section-heading"><div><p className="eyebrow">{t.categoryEyebrow}</p><h2>{t.categoryTitle}</h2></div><p>{t.categoryIntro}</p></div><div className="category-grid">{displayCategories[locale].map(([name,detail],i)=><a key={name} href={`https://findspreadsheet.com${categoryLinks[i]}`} target="_blank" rel="noreferrer" className="category-card"><span className={`category-photo category-photo--${i+1}`} aria-hidden="true"/><span className="category-shade" aria-hidden="true"/><span className="category-copy"><strong>{name}</strong><small>{detail}</small></span><span className="category-cta">{categoryCta[locale]}<ArrowRight/></span></a>)}</div></section>}
    {show("product-details")&&<section className="detail-section" id="product-details"><div className="section-heading"><div><p className="eyebrow">{t.detailsEyebrow}</p><h2>{t.detailsTitle}</h2></div><p>{t.detailsIntro}</p></div><div className="product-grid">{t.products.map(([title,text],i)=><a className="product-card" key={title} href={`https://findspreadsheet.com${productLinks[i]}`} target="_blank" rel="noreferrer"><span className="product-card__number">0{i+1}</span><div className={`product-art product-art--${i+1}`}><PackageCheck/></div><h3>{title}</h3><p>{text}</p><strong>{t.viewDetails}<ArrowRight/></strong></a>)}</div></section>}
    {show("how-it-works")&&<section className="process-section" id="how-it-works"><div className="section-heading section-heading--light"><div><p className="eyebrow">{t.processEyebrow}</p><h2>{t.processTitle}</h2></div><p>{t.processIntro}</p></div><div className="guide-grid">{t.guides.map(([step,title,text],i)=>{const Icon=[Search,PackageCheck,Truck][i];return <article className="guide-card" key={title}><div className="guide-icon"><Icon/></div><p>{step}</p><h3>{title}</h3><span>{text}</span></article>})}</div></section>}
    {show("shipping")&&<section className="shipping-section" id="shipping"><div className="shipping-copy"><p className="eyebrow">{t.shippingEyebrow}</p><h2>{t.shippingTitle}</h2><p>{t.shippingText}</p><ul>{t.shippingList.map(x=><li key={x}><Check/>{x}</li>)}</ul><a className="text-link" href={MAIN_SITE} target="_blank" rel="noreferrer">{t.database}<ExternalLink size={16}/></a></div><aside className="fact-card"><div className="fact-card__head"><Globe2/><span><strong>{t.marketTitle}</strong><small>{t.marketSub}</small></span></div><div className="locale-grid">{locales.map(code=><button type="button" key={code} onClick={()=>changeLocale(code)} className={code===locale?"active":""}><strong>{code.toUpperCase()}</strong><span>{languageNames[code]}</span></button>)}</div><p><CircleAlert size={16}/>{t.marketNote}</p></aside></section>}
    {show("seo-articles")&&<section className="seo-section" id="seo-articles"><div className="section-heading"><div><p className="eyebrow">{t.seoEyebrow}</p><h2>{t.seoTitle}</h2></div><p>{t.seoIntro}</p></div><div className="article-grid">{t.articles.map(([title,text],i)=>{const slug=["lolobuy-spreadsheet-guide","lolobuy-qc-photo-checklist","lolobuy-international-shipping-guide"][i];return <article key={title} id={`article-${i+1}`}><span>0{i+1} · {articleLengthLabel[locale]}</span><h3>{title}</h3><p>{text}</p><a href={locale==="en"?`/articles/${slug}`:`/${locale}/articles/${slug}`}>{t.readArticle}<ArrowRight/></a></article>})}</div></section>}
    {show("faq")&&<section className="faq-section" id="faq"><div className="section-heading"><div><p className="eyebrow">{t.faqEyebrow}</p><h2>{t.faqTitle}</h2></div><p>{t.faqIntro}</p></div><div className="faq-list">{officialFaqs[locale].map(([q,a],i)=><details key={q} open={i===0}><summary>{q}<span>+</span></summary><p>{a}</p></details>)}</div></section>}
    <section className="database-cta"><div><p className="eyebrow">{t.ready}</p><h2>{t.ctaTitle}</h2><p>{t.ctaText}</p></div><MainSearch t={t} compact/></section>
    <footer><div className="brand brand--footer brand-image"><img src="/lolobuy-logo.png" alt="LoloBuy"/></div><p>{t.disclosure}</p><div><a href={MAIN_SITE} target="_blank" rel="noreferrer">{t.footerLinks[0]}</a><a href={`${home}/faq`}>{t.footerLinks[1]}</a><a href={`${home}/seo-articles`}>{t.footerLinks[2]}</a></div><small>{t.checked}</small></footer>
  </main>
}
